import ast

def score(program: str) -> float:
    try:
        tree = ast.parse(program)
        for node in ast.walk(tree):
            if isinstance(node, ast.FunctionDef) and node.name == 'score':
                func_nodes = sum(1 for _ in ast.walk(node))
                return min(1.0, func_nodes / 50)
        return 0
    except:
        return 0

def score(program: str) -> float:
