import ast

def score(program: str) -> float:
    n = len(program)
    try:
        t = ast.parse(program)
        nodes = list(ast.walk(t))
        k = len({type(x).__name__ for x in nodes})
        return 0.5 * n / (n + 300) + 0.5 * k / (k + 20)
    except Exception:
        return 0.1

import re

def score(program: str) -> float:
    if not isinstance(program, str):
        return 0.0
    text = re.sub(r"#[^\n]*", "", program)
    body = re.sub(r"\s+", "", text)
    n = len(body)
    return min(1.0, n / 1200.0)

